DO $$ DECLARE f text;BEGIN SELECT pg_get_functiondef('public.client_approve_task(uuid,text)'::regprocedure) INTO f;f:=replace(f,'t.status <> ''waiting_client''','NOT (t.status = ''waiting_client'' OR (t.status = ''blocked'' AND t.blocker_reason = ''Waiting on client approval''))');EXECUTE f;END $$;
CREATE OR REPLACE FUNCTION public.blocked_task_reason(_kind text,_id uuid,_reason text,_impact text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t recurring_tasks;cp client_pipelines;BEGIN PERFORM activity_require_ready();IF _kind<>'recurring' OR coalesce(btrim(_impact),'')='' OR _reason NOT IN('Waiting on client approval','Other blocker') THEN RAISE EXCEPTION 'Choose a blocker reason and describe its impact';END IF;SELECT * INTO t FROM recurring_tasks WHERE id=_id;SELECT c.* INTO cp FROM client_pipelines c JOIN activity_plans p ON p.client_pipeline_id=c.id WHERE p.id=t.plan_id;IF t.id IS NULL OR NOT activity_can_read(cp.id) OR has_role(auth.uid(),'client') OR NOT (activity_can_head(cp.id) OR auth.uid() IN(t.owner_id,t.backup_id)) THEN RAISE EXCEPTION 'Task owner, backup or head only';END IF;IF client_on_hold(cp.client_id) THEN RAISE EXCEPTION 'This hotel is on hold';END IF;IF t.status NOT IN('blocked','waiting_client') THEN RAISE EXCEPTION 'Block the task first';END IF;UPDATE recurring_tasks SET blocker_reason=_reason,blocker_impact=btrim(_impact) WHERE id=_id;END $$;
REVOKE ALL ON FUNCTION public.blocked_task_reason(text,uuid,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.blocked_task_reason(text,uuid,text,text) TO authenticated,service_role;
DO $$ DECLARE f text;BEGIN SELECT pg_get_functiondef('public.request_pipeline_activation(text)'::regprocedure) INTO f; f:=replace(f,'BEGIN\n  IF v_client','BEGIN\n  IF v_client'); f:=replace(f,'p.code IN (''business_development'', _pipeline_code)','p.code = ''business_development'''); EXECUTE f;END $$;